"""Build three self-contained, interactive visual prototypes from local fictional examples."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'backend'))
from semantics_data import SAMPLES, TERMS

OUT = Path(__file__).parent
data = json.dumps({'samples': SAMPLES, 'terms': TERMS}, ensure_ascii=False)

script = r'''
const DATA=__DATA__;let scene='contract';
const $=id=>document.getElementById(id);
function add(tag,txt,parent,cls=''){const e=document.createElement(tag);e.textContent=txt;if(cls)e.className=cls;parent.appendChild(e);return e}
function loadScene(v){scene=v;const sample=DATA.samples.find(s=>s.scene===scene);$('docInput').value=sample.text;$('docTitle').textContent=sample.title;$('question').value=sample.questions[0];$('questionHints').replaceChildren();sample.questions.forEach(q=>{const b=add('button',q,$('questionHints'));b.onclick=()=>{$('question').value=q;ask()}});analyze()}
function analyze(){const text=$('docInput').value;if(!text.trim()){alert('请填写需要分析的文本');return}const terms=DATA.terms[scene].filter(t=>[t[0],...t[3]].some(w=>text.includes(w)));$('termList').replaceChildren();terms.forEach(t=>{const b=add('button',t[0],$('termList'),'term-chip');b.onclick=()=>{$('termTitle').textContent=t[0]+' → '+t[1];$('termDetail').textContent=t[2]}});$('summary').textContent=text.split('\n').filter(s=>s.length>20).slice(0,2).join(' ');$('mappedCount').textContent=terms.length;$('entityList').replaceChildren();const vals=[...new Set(text.match(/20\d{2}年\d{1,2}月\d{1,2}日|\d[\d,]*元|\d+%|[A-Z]{2}-\d{4}-\d{3}/g)||[])];vals.forEach(v=>add('span',v,$('entityList'),'entity'));$('entityCount').textContent=vals.length;$('termTitle').textContent=terms[0]?terms[0][0]+' → '+terms[0][1]:'没有命中词条';$('termDetail').textContent=terms[0]?terms[0][2]:'可调整文本或添加术语。';$('docText').replaceChildren();let pos=0;const word=terms.find(t=>t[0]==='交付')?.[0]||terms[0]?.[0];if(word){for(const m of text.matchAll(new RegExp(word,'g'))){add('span',text.slice(pos,m.index),$('docText'));const btn=add('button',word,$('docText'),'inline-term');btn.onclick=()=>{const term=terms.find(t=>t[0]===word);$('termTitle').textContent=word+' → '+term[1];$('termDetail').textContent=term[2]};pos=m.index+word.length}}add('span',text.slice(pos),$('docText'));$('resultNote').textContent='本地样例解析完成 · 当前规则版本 v1';$('answer').textContent='点击一个问题，查看可核对的原文依据。';$('evidence').textContent='';}
function ask(){const q=$('question').value;const text=$('docInput').value;const cues=[[/期限|多久/,['期限']],[/金额|总价/,['总价']],[/交付|验收/,['交付','验收']],[/问题|异常/,['反馈','问题由']],[/负责|恢复/,['负责人','计划在']],[/关闭/,['关闭工单']],[/营收|增长/,['营收']],[/订阅|占比/,['占比']],[/建议/,['建议']]];const keys=cues.find(([r])=>r.test(q))?.[1]||[];const found=text.split('\n').filter(s=>keys.some(k=>s.includes(k))).slice(0,2);$('answer').textContent=found.length?'根据当前原文：'+found.join(' '):'原文中未找到足够依据。';$('evidence').textContent=found.length?'原文依据：'+found[0]:'';}
function edit(){const on=$('docInput').hidden;$('docInput').hidden=!on;$('docText').hidden=on;$('editButton').textContent=on?'查看高亮':'编辑原文'}
document.querySelectorAll('[data-local-nav]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-local-nav]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('resultNote').textContent='此初稿展示当前分析界面；'+b.textContent+'将在正式版接入。'});
loadScene('contract');
'''.replace('__DATA__', data)

